#!/usr/bin/env python3
"""Add guarded R1 unlearning and evaluation stages to the Kaggle notebook."""
import json
from pathlib import Path

root=Path(__file__).resolve().parents[1]
path=root/"kaggle/sft_lora_pilot.ipynb"
nb=json.loads(path.read_text(encoding="utf-8"))
cells=nb["cells"]
if any("English-only unlearning" in "".join(c.get("source",[])) for c in cells):
    print("R1 stages already present")
    raise SystemExit(0)

def md(s): return {"cell_type":"markdown","metadata":{},"source":s.splitlines(keepends=True)}
def code(s): return {"cell_type":"code","execution_count":None,"metadata":{},"outputs":[],"source":s.splitlines(keepends=True)}

cells.extend([
md("""## 3. English-only unlearning and multilingual evaluation\n\nThe stages below implement the R1 pilot: full five-language SFT, an English-only retain-set reference, and GA/GD/NPO updates on English forget rows. Evaluation supplies only translated questions to the model; gold labels are opened by the scoring stage after generation. Holdout examples are never used for SFT or unlearning.\n\nAll run switches remain `False` until the preflights have visibly passed. The evaluator requires a complete four-language AI-only reviewed prompt set. This is clearly labeled AI-only and is not human linguistic validation.\n"""),
code("""# Enable stages only after all displayed gates pass. Kaggle GPU time is consumed by each enabled stage.\nRUN_RETAIN_ONLY = False\nRUN_UNLEARNING = False\nRUN_EVALUATION = False\nMETHODS = (\"ga\", \"gd\", \"npo\")\nRETAIN_DIR = Path('/kaggle/working/r1_retain_only')\nUNLEARN_ROOT = Path('/kaggle/working/r1_unlearning')\nEVAL_ROOT = PROJECT_ROOT / 'evaluation_dataset'\nEVAL_OUT = Path('/kaggle/working/r1_diagnostics')\n\nEVAL_MANIFEST = EVAL_ROOT / 'manifest.json'\nif not EVAL_MANIFEST.is_file():\n    raise FileNotFoundError('R1 evaluation dataset is absent from the attached package.')\neval_manifest = json.loads(EVAL_MANIFEST.read_text())\nEVAL_READY = (eval_manifest.get('evaluation_ready') is True and\n              eval_manifest.get('ai_review_status') == 'AI_ONLY_REVIEWED_COMPLETE' and\n              eval_manifest.get('human_review_status') == 'NOT_PERFORMED')\nprint('AI-only translation review:', eval_manifest.get('ai_review_status'))\nprint('Human review:', eval_manifest.get('human_review_status'))\nprint('Evaluation gate:', 'READY' if EVAL_READY else 'BLOCKED')\n"""),
md("""### 3.1 Retain-only reference checkpoint\n\nThis separate adapter starts from the same base model and trains only on the English plus translated retain split rows selected by `--include-splits retain`. It is a comparison checkpoint; it does not receive forget or holdout rows.\n"""),
code("""if RUN_RETAIN_ONLY:\n    if not CAN_TRAIN:\n        raise RuntimeError('Hugging Face access, GPU, or corpus preflight is not ready.')\n    subprocess.run([sys.executable, str(runner), '--corpus', str(CORPUS), '--manifest', str(MANIFEST),\n                    '--output-dir', str(RETAIN_DIR), '--include-splits', 'retain', '--train'], check=True)\nelse:\n    print('Retain-only training not started.')\n"""),
md("""### 3.2 English-only GA, GD, and NPO\n\nEach method begins from the same full-SFT adapter. Forget and retain updates use English examples only. GA maximizes forget-answer NLL; GD combines this with a retain-answer CE regularizer; NPO compares forget likelihood with a frozen SFT reference and adds the same retain regularizer. The script refuses any holdout use and reports the exact configuration.\n"""),
code("""UNLEARN_RUNS = {}\nif RUN_UNLEARNING:\n    if not CAN_TRAIN:\n        raise RuntimeError('Hugging Face access, GPU, or corpus preflight is not ready.')\n    sft_run_manifest = RUN_DIR / 'run_manifest.json'\n    if not sft_run_manifest.is_file():\n        raise FileNotFoundError('Complete the full SFT stage first; run_manifest.json is missing.')\n    unlearn_script = PROJECT_ROOT / 'scripts' / 'unlearn_lora.py'\n    # Validate the exact SFT/corpus pairing for every method before spending GPU time.\n    for method in METHODS:\n        out = UNLEARN_ROOT / method\n        cmd = [sys.executable, str(unlearn_script), '--corpus', str(CORPUS),\n               '--corpus-manifest', str(MANIFEST), '--sft-run-manifest', str(sft_run_manifest),\n               '--output-dir', str(out), '--method', method]\n        check = subprocess.run(cmd, check=True, text=True, capture_output=True)\n        report = json.loads(check.stdout)\n        print(method.upper(), 'preflight:', report.get('status'), report.get('errors', []))\n        if report.get('status') != 'READY_TO_UNLEARN':\n            raise RuntimeError(f'{method.upper()} unlearning preflight failed: {report}')\n    for method in METHODS:\n        out = UNLEARN_ROOT / method\n        cmd = [sys.executable, str(unlearn_script), '--corpus', str(CORPUS),\n               '--corpus-manifest', str(MANIFEST), '--sft-run-manifest', str(sft_run_manifest),\n               '--output-dir', str(out), '--method', method, '--train']\n        subprocess.run(cmd, check=True)\n        run = json.loads((out / 'run_manifest.json').read_text())\n        if (run.get('status') != 'UNLEARNING_COMPLETE' or run.get('holdout_rows_used') != 0\n                or run.get('english_forget_rows') != 76 or run.get('english_retain_rows') != 26):\n            raise RuntimeError(f'{method.upper()} unlearning output failed validation: {run}')\n        UNLEARN_RUNS[method] = out / 'run_manifest.json'\n        print(method.upper(), 'complete; English r1 rows:', run['english_forget_rows'], 'forget +',\n              run['english_retain_rows'], 'retain; holdout rows used:', run['holdout_rows_used'])\nelse:\n    print('Unlearning not started.')"""),
md("""### 3.3 Baseline and post-unlearning evaluation\n\nGeneration is question-only, greedy, and runs before the label file is read. Exact normalized answer matching is used; generation failures count as incorrect. The report includes full-set performance, performance on cases both answered correctly by SFT, paired bootstrap intervals, retain/holdout controls, and DAP.\n"""),
code("""if RUN_EVALUATION:\n    if not EVAL_READY:\n        raise RuntimeError('Evaluation is blocked until all four translations are complete and pass AI-only review import.')\n    sft_run_manifest = json.loads((RUN_DIR/'run_manifest.json').read_text())\n    checkpoint_args = ['--checkpoint', 'pretrained=base', '--checkpoint', f\"sft={sft_run_manifest['adapter_dir']}\"]\n    if not RETAIN_DIR.joinpath('run_manifest.json').is_file():\n        raise FileNotFoundError('Train the retain-only reference first.')\n    retain_run = json.loads(RETAIN_DIR.joinpath('run_manifest.json').read_text())\n    checkpoint_args += ['--checkpoint', f\"retain_only={retain_run['adapter_dir']}\"]\n    for method in METHODS:\n        run_file = UNLEARN_ROOT / method / 'run_manifest.json'\n        if not run_file.is_file():\n            raise FileNotFoundError(f'Missing unlearning output for {method}.')\n        run = json.loads(run_file.read_text())\n        checkpoint_args += ['--checkpoint', f\"{method.upper()}={run['adapter_dir']}\"]\n    evaluator = PROJECT_ROOT/'scripts'/'evaluate_crosslingual_unlearning.py'\n    subprocess.run([sys.executable, str(evaluator), '--eval-root', str(EVAL_ROOT), '--output-dir', str(EVAL_OUT), *checkpoint_args], check=True)\n    print('Diagnostic report:', EVAL_OUT/'diagnostic_report.md')\nelse:\n    print('Evaluation not started.')\n"""),
md("""## Outputs and interpretation\n\nKeep `/kaggle/working/r1_diagnostics/predictions.jsonl`, `summary.csv`, `summary.json`, and `diagnostic_report.md` together with all run manifests. The results are a small AI-only feasibility pilot (77 forget, 26 retain, 26 holdout chains), not the report's planned powered 8B main study. Do not interpret AI-only translation review as native-speaker validation.\n""")
])
path.write_text(json.dumps(nb,ensure_ascii=False,indent=1)+"\n",encoding="utf-8")
print(f"Updated {path} with {len(cells)} cells")
